  const char *name=info.dli_fname?strrchr(info.dli_fname,'/'):nullptr;
  snprintf(out,size,"%.14s+%llx",name?name+1:"?",(unsigned long long)((uintptr_t)address-(uintptr_t)info.dli_fbase));
